__bundle_register("TTS_lib.Vector.Vector", function(require, _LOADED, __bundle_register, __bundle_modules)
-- ~~~~~~
-- Script by dzikakulka
-- Issues, history at: http://github.com/tjakubo2/TTS_lib
--
-- Library for all vector-related operations
-- Description and usage in README.md in this lib folder in repository
-- ~~~~~~

-- TODO: Many of these now have TTS equivalents.
-- TODO: e.g. Vector.__add(vec1, vec2)

local Vect = {}

require("TTS_Lib.Util.Math")

-- Sum of two vectors (of any size)
Vect.Sum = function(vec1, vec2)
    assert(type(vec1) == 'table', 'Vect.Sum: arg#1 not a table!')
    assert(type(vec2) == 'table', 'Vect.Sum: arg#2 not a table!')
    local out = {}
    local k = 1
    while vec1[k] ~= nil and vec2[k] ~= nil do
        out[k] = vec1[k] + vec2[k]
        k = k + 1
    end
    return out
end

-- Inverse of a vector
Vect.Inverse = function(vector)
    assert(type(vector) == 'table', 'Vect.Inverse: arg#1 not a table!')
    local out = {}
    local k = 1
    while vector[k] ~= nil do
        out[k] = 1 / vector[k]
        k = k + 1
    end
    return out
end

-- Multiply each element of a vector by a factor
Vect.Scale = function(vector, factor)
    assert(type(vector) == 'table', 'Vect.Scale: arg#1 not a table!')
    assert(type(factor) == 'number', 'Vect.Scale: arg#2 not a number!')
    local out = {}
    local k = 1
    while vector[k] ~= nil do
        out[k] = vector[k] * factor
        k = k + 1
    end
    return out
end

-- Multiply each element of a vector by an element from factor vector
-- (element-wise vector multiplication)
Vect.ScaleEach = function(vector, factorVec)
    assert(type(vector) == 'table', 'Vect.ScaleEach: arg#1 not a table!')
    assert(type(factorVec) == 'table', 'Vect.ScaleEach: arg#2 not a table!')
    local out = {}
    local k = 1
    while vector[k] ~= nil and factorVec[k] ~= nil do
        out[k] = vector[k] * factorVec[k]
        k = k + 1
    end
    return out
end


-- Length of  vector on X-Z plane (ignoring height)
Vect.Length = function(vector)
    assert(type(vector) == 'table', 'Vect.Length: arg#1 not a table!')
    return math.sqrt(vector[1] * vector[1] + vector[3] * vector[3])
end

-- Rotation of a 3D vector over its second element axis, arg in radians
-- Elements past 3rd are copied
Vect.RotateRad = function(vector, radRotation)
    assert(type(vector) == 'table', 'Vect.RotateRad: arg#1 not a table!')
    assert(type(radRotation) == 'number', 'Vect.RotateRad: arg#2 not a number!')
    local newX = math.cos(radRotation) * vector[1] + math.sin(radRotation) * vector[3]
    local newZ = math.sin(radRotation) * vector[1] * -1 + math.cos(radRotation) * vector[3]
    local out = { newX, vector[2], newZ }
    local k = 4
    while vector[k] ~= nil do
        table.insert(out, vector[k])
        k = k + 1
    end
    return out
end

-- Distance between two points
-- Points as vectors or objects (their positions)
Vect.Distance = function(pos1, pos2)
    assert(type(pos1) == 'table' or type(pos1) == 'userdata', 'Vect.Distance: arg#1 not a table/object!')
    assert(type(pos2) == 'table' or type(pos2) == 'userdata', 'Vect.Distance: arg#2 not a table/object!')
    if type(pos1) == 'userdata' then
        pos1 = pos1.getPosition()
    end
    if type(pos2) == 'userdata' then
        pos2 = pos2.getPosition()
    end
    return Vect.Length(Vect.Between(pos1, pos2))
end

-- Print vector elements
Vect.Print = function(vec, name)
    assert(type(vec) == 'table', 'Vect.Print: arg#1 not a table!')
    local out = '['
    if name then
        out = name .. ' => ' .. out
    end
    local k = 1
    while vec[k] ~= nil do
        out = out .. math.round(vec[k], 3) .. ' : '
        k = k + 1
    end
    out = out:sub(1, -3) .. ']'
    print(out)
end

-- Dot product
Vect.DotProd = function(vec1, vec2)
    assert(type(vec1) == 'table', 'Vect.DotProd: arg#1 not a table!')
    assert(type(vec2) == 'table', 'Vect.DotProd: arg#2 not a table!')
    local sum = 0
    local k = 1
    while vec1[k] ~= nil and vec2[k] ~= nil do
        sum = sum + vec1[k] * vec2[k]
        k = k + 1
    end
    return sum
end

-- Element-by-element comparison
-- Fails if length uneven
Vect.Compare = function(vec1, vec2)
    assert(type(vec1) == 'table', 'Vect.Compare: arg#1 not a table!')
    assert(type(vec2) == 'table', 'Vect.Compare: arg#2 not a table!')
    if #vec1 ~= #vec2 then
        return false
    end
    local k = 1
    while vec1[k] ~= nil and vec2[k] ~= nil do
        if vec1[k] ~= vec2[k] then
            return false
        end
        k = k + 1
    end
    return true
end

-- Euclidean norm
Vect.Norm = function(vec)
    local selfDot = Vect.DotProd(vec, vec)
    return math.sqrt(selfDot)
end

-- Convert a vector to unit vector in the same direction
-- Return zero vector for zero vector
Vect.ToUnit = function(vec)
    if Vect.Norm(vec) == 0 then
        return vec
    end
    return Vect.Scale(vec, 1 / Vect.Norm(vec))
end

-- Angle between vectors in radians
-- If second argument not provided, calculate typical angle (from [1, 0, 0, ...] )
Vect.Angle = function(vec1, vec2)
    if vec2 == nil then
        vec2 = { 1 }
        for k = 2, #vec1, 1 do
            table.insert(vec2, 0)
        end
    end
    return math.acos(Vect.DotProd(vec1, vec2) / (Vect.Norm(vec1) * Vect.Norm(vec2)))
end

-- Angle between vectors in radians, in plane
-- If second argument not provided, calculate typical angle (from [1, 0, 0, ...] )
Vect.Angle2D = function(vec1, vec2)
    if vec2 == nil then
        vec2 = { 1 }
        for k = 2, #vec1, 1 do
            table.insert(vec2, 0)
        end
    end
    return (math.atan2(vec2[3], vec2[1]) - math.atan2(vec1[3], vec1[1]))
end

-- Same as Vect.Angle but in degrees
Vect.AngleDeg = function(vec1, vec2)
    return math.deg(Vect.Angle(vec1, vec2))
end

-- Same as Vect.Angle2D but in degrees
Vect.AngleDeg2D = function(vec1, vec2)
    return math.deg(Vect.Angle2D(vec1, vec2))
end

-- Vector pointing from one position to another
Vect.Between = function(fromVec, toVec)
    return Vect.Sum(toVec, Vect.Scale(fromVec, -1))
end

-- Vector pointing between two points
Vect.Middle = function(p1, p2)
    return Vect.Sum(p1, Vect.Scale(Vect.Between(p1, p2), 0.5))
end

-- Subtract vector from another
Vect.Sub = function(vec1, vec2)
    return Vect.Sum(vec1, Vect.Scale(vec2, -1))
end

-- Opposite of a vector
Vect.Opposite = function(vector)
    return Vect.Scale(vector, -1)
end

-- Rotation of a 3D vector over its second element axis, arg in degrees
-- Elements past 3rd are copied
Vect.RotateDeg = function(vector, degRotation)
    local radRotation = math.rad(degRotation)
    return Vect.RotateRad(vector, radRotation)
end

-- Scale the vector to have set length
-- Negative "length" - opposite of set length
Vect.SetLength = function(vector, len)
    return Vect.Scale(vector, len / Vect.Length(vector))
end

return Vect

end)
__bundle_register("TTS_Lib.Util.Math", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Round to decPlaces decimal places
-- if decPlaces nil round to nearest integer
if not math.round then
    math.round = function(arg, decPlaces)
        decPlaces = decPlaces or 0
        if decPlaces == 0 then
            return math.floor(arg + 0.5)
        end
        local mult = 10 ^ decPlaces
        return math.floor(arg * mult + 0.5) / mult
    end
end

-- Return value limited by min and max bounds
if not math.clamp then
    math.clamp = function(var, min, max)
        return (var < min and min) or (var > max and max) or var
    end
end

-- Sign function, zero for zero
if not math.sgn then
    math.sgn = function(arg)
        return arg < 0 and -1 or arg > 0 and 1 or 0
    end
end

return math

end)
__bundle_register("TTS_Lib.EventSub.EventSub", function(require, _LOADED, __bundle_register, __bundle_modules)
-- ~~~~~~
-- Script by dzikakulka
-- Issues, history at: http://github.com/tjakubo2/TTS_lib
--
-- Simple framework for adding many subscribers of default events (onLoad, update, onChat etc)
-- Description and usage in README.md in this lib folder in repository
-- ~~~~~~

-- Table mapping event names to table of handler functions
local EventSub = {
    subs = {}
}

-- Initialize subscriber table for given event function, save current one if exists
EventSub.AddEvent = function(eventName)
    EventSub.subs[eventName] = {}
    if type(_G[eventName]) == 'function' then
        table.insert(EventSub.subs[eventName], _G[eventName])
    end
    -- Set the global event function to call each handler pasing its parameters
    _G[eventName] = function(...)
        for _, handler in ipairs(EventSub.subs[eventName]) do
            handler(table.unpack({ ... }))
        end
    end
end
-- Method for adding subscribers
EventSub.Register = function(eventName, handler)
    assert(type(eventName) == 'string', 'EventSub.Register: Provided event name not a string!')
    assert(type(handler) == 'function', 'EventSub.Register: Provided handler not a function!')
    if not EventSub.subs[eventName] then
        EventSub.AddEvent(eventName)
    end
    table.insert(EventSub.subs[eventName], handler)
end

return EventSub

end)
__bundle_register("Test.luaunit_tts", function(require, _LOADED, __bundle_register, __bundle_modules)
--- @module luaunit_tts
-- Bootstrap for the TTS LuaUnit port: loads core runner, env shim, multi-output,
-- auto-inits on require, and wraps all entry points in coroutines by name.

local lu = require("Test.luaunit")
require("Test.luaunit_tts_env")
local TTSOutput = require("Test.luaunit_tts_output")
TTSOutput.currentRunner = nil

--- Initialize the TTS LuaUnit port.
--- @param scriptOwner :LuaGameObjectScript  drives coroutines & chat/log output
--- @param gridOwner   :LuaGameObjectScript? where the Grid UI attaches
function lu.init(scriptOwner, gridOwner)
    assert(scriptOwner, "luaunit_tts.init: scriptOwner is required")
    lu.LuaUnit.scriptOwner = scriptOwner
    TTSOutput.gridOwner = gridOwner or scriptOwner
    lu.LuaUnit.outputType = TTSOutput
end

-- Auto‐initialize when required inside a TTS object script
local _self = rawget(_G, "self")
if _self then
    lu.init(_self)
end

-- Wrap all core runner methods so they execute inside a named TTS coroutine.
local function wrapWithCoroutine(methodName)
    local orig = lu.LuaUnit[methodName]
    lu.LuaUnit[methodName] = function(self, ...)
        assert(self.scriptOwner,
                "luaunit_tts: call luaunit_tts.init(self[, gridOwner]) in onLoad")
        local args = { ... }
        local coroName = "__luaunit_" .. methodName .. "_coro"
        TTSOutput.currentRunner = self
        
        _G[coroName] = function()
            orig(self, table.unpack(args))
            return 1
        end
        
        startLuaCoroutine(self.scriptOwner, coroName)
    end
end

local methods = { "run", "runSuite", "runSuiteByNames", "runSuiteByInstances" }
for _, method in ipairs(methods) do
    wrapWithCoroutine(method)
end

--- Yield the test coroutine until a condition is met
--- @param conditionFunc function():boolean
function lu.await(conditionFunc)
    return coroutine.yield(conditionFunc)
end

return lu

end)
__bundle_register("Test.luaunit_tts_output", function(require, _LOADED, __bundle_register, __bundle_modules)
--[[────────────────────────────────────────────────────────────────────────────
    LuaUnit Multi-Output Handler for TTS
    Drop-in replacement to route LuaUnit output to multiple destinations
    (chat, system log, grid GUI) while reusing LuaUnit formatters.
────────────────────────────────────────────────────────────────────────────]] --

local M = require("Test.luaunit")

--[[
    TTSOutput: These are the defaults for the TTSOutput object:
    * chat: ChatOutput (default: enabled) uses verbose output in TAP format to the chat window.
    * log: LogOutput (default: enabled) uses low verbosity output in TEXT format to the system console.
    * grid: GridOutput (default: enabled if gridOwner exists) uses a clickable GUI grid to show test results.
    * colors: color scheme for all outputs (default: see below) can easily be overridden by the user.
    * yieldFrequency: (default: 10) number of tests between each coroutine.yield
]]
--- @class TTSOutput: genericOutput
TTSOutput = {
    chat = { format = "TAP", verbosity = M.VERBOSITY_VERBOSE },
    log = { format = "TEXT", verbosity = M.VERBOSITY_LOW },
    grid = true,
    gridOwner = nil, -- set to the object that owns the UI (usually self)
    yieldFrequency = 10, -- number of tests between each coroutine.yield
    
    -- Colors used by all outputs
    colors = {
        [M.NodeStatus.SUCCESS] = "#00FF00", -- bright green (test passed)
        [M.NodeStatus.FAIL] = "#FF0000", -- bright red (test failed)
        [M.NodeStatus.ERROR] = "#FF6600", -- dark orange (test had runtime error)
        [M.NodeStatus.SKIP] = "#FFFF00", -- yellow (test skipped)
        INFO = "#FFFDD0", -- cream (generic info)
        UNKNOWN = "#FF00FF", -- magenta
    },
    
    -- Factory method for LuaUnit's outputType.new() call
    new = function(runner)
        return buildTTSOutput(runner, TTSOutput)
    end
}

--[[────────────────────────────────────────────────────────────────────────────
    TTSMultiOutput: Composite root that delegates to child outputs
────────────────────────────────────────────────────────────────────────────]] --
--- @class TTSMultiOutput: genericOutput
local TTSMultiOutput = { __class__ = "TTSMultiOutput" }
TTSMultiOutput.__index = TTSMultiOutput
setmetatable(TTSMultiOutput, { __index = M.genericOutput })

function TTSMultiOutput.new(runner)
    local t = M.genericOutput.new(runner)
    t.children = {}
    return setmetatable(t, TTSMultiOutput)
end

function TTSMultiOutput:add(child)
    table.insert(self.children, child)
end

-- Delegate all lifecycle methods to child outputs
setmetatable(TTSMultiOutput, {
    __index = function(_, method)
        return function(self, ...)
            for _, child in ipairs(self.children) do
                if child[method] then
                    child[method](child, ...)
                end
            end
        end
    end
})

--[[────────────────────────────────────────────────────────────────────────────
    Output Class Hierarchy:

    M.genericOutput (LuaUnit base)
    ├── TTSMultiOutput (TTS port - composite, delegates to children)
    │
    ├── OUTPUT FORMATTERS (LuaUnit base - what to output)
    │   ├── M.TextOutput (human readable format)
    │   └── M.TapOutput (human/machine readable format)
    │
    ├── OUTPUT DECORATORS (TTS port - where to output)
    │   ├── ChatOutput (decorates any formatter with colored output to chat window)
    │   └── LogOutput (decorates any formatter with output to system console)
    │
    ├── DIRECT OUTPUTS (TTS port - special destinations)
    │   └── GridOutput (visual GUI grid, subclasses genericOutput directly)
    │
    └── YieldOutput (TTS port - controls coroutine yieldFrequency)
────────────────────────────────────────────────────────────────────────────]] --

local FormatterDecorator = {}
function FormatterDecorator._init(decorator, runner, colors, config)
    local formatter = (config.format == "TAP") and M.TapOutput or M.TextOutput
    local self = formatter.new(runner)
    
    self.colors = colors or TTSOutput.colors
    self.verbosity = config.verbosity or M.VERBOSITY_DEFAULT
    for k, v in pairs(_G.Emitter) do
        self[k] = v
    end
    self:init()
    
    return setmetatable(self, {
        __index = function(_, k)
            return decorator[k] or formatter[k]
        end
    })
end

local _colorCache = {}
local function colorFromHex(hex)
    local c = _colorCache[hex]
    if not c then
        c = Color.fromHex(hex)
        _colorCache[hex] = c
    end
    return c
end

local function statusColor(colors, status)
    return colors[status] or colors.INFO
end

--[[────────────────────────────────────────────────────────────────────────────
    ChatOutput: Colored chat window output wrapping TextOutput or TapOutput formatting
────────────────────────────────────────────────────────────────────────────]] --
--- @class ChatOutput wraps either TextOutput or TapOutput
local ChatOutput = { __class__ = "ChatOutput" }
ChatOutput.__index = ChatOutput

function ChatOutput.new(runner, colors, config)
    return FormatterDecorator._init(ChatOutput, runner, colors, config)
end

function ChatOutput:flush(line)
    local node = self.result.currentNode
    local hex = statusColor(self.colors, node and node.status or "INFO")
    printToAll(line, colorFromHex(hex))
end

--[[────────────────────────────────────────────────────────────────────────────
    LogOutput: System console output wrapping TextOutput or TapOutput formatting
────────────────────────────────────────────────────────────────────────────]] --
--- @class LogOutput wraps either TextOutput or TapOutput
local LogOutput = { __class__ = "LogOutput" }
LogOutput.__index = LogOutput

function LogOutput.new(runner, colors, config)
    return FormatterDecorator._init(LogOutput, runner, colors, config)
end

function LogOutput:flush(line)
    log(line)
end

--[[────────────────────────────────────────────────────────────────────────────
    GridOutput: Grid-based UI output for TTS
────────────────────────────────────────────────────────────────────────────]] --
local function resolveClickFunc(name)
    local prefix = (M.LuaUnit.scriptOwner == Global) and "Global/" or ""
    return prefix .. name
end

local function buildGridUI(originPos)
    local clickFunc = resolveClickFunc("onCloseButtonClick")
    
    local testGrid = {
        tag = "GridLayout",
        attributes = {
            id = "TestGrid",
            cellSize = "50 50",
            spacing = "6 6",
            padding = "10 10 10 10",
            constraint = "FixedColumnCount",
            constraintCount = "10",
            color = "#222222",
            alignment = "UpperCenter"
        },
        children = {}
    }
    local ui = {
        {
            tag = "Defaults",
            attributes = {},
            children = {
                {
                    tag = "Text",
                    attributes = {
                        alignment = "MiddleCenter",
                        class = "title",
                        color = "White",
                        fontStyle = "Bold",
                        resizeTextForBestFit = "true"
                    },
                    children = {},
                }
            },
        },
        {
            tag = "Panel",
            attributes = {
                id = "TestStatus",
                width = "650",
                height = "700",
                position = originPos or "0 350 -50",
                color = "#666666",
                active = "true"
            },
            children = {
                {
                    tag = "Button",
                    attributes = {
                        id = "CloseButton",
                        text = "✕",
                        width = "60",
                        height = "60",
                        position = "280 305 0", -- Adjusted for upper-right corner
                        alignment = "UpperRight",
                        color = "#DDDDDD",
                        fontStyle = "Bold",
                        textColor = "#FF2222",
                        resizeTextForBestFit = "true",
                        onClick = clickFunc
                    }
                },
                {
                    tag = "VerticalLayout",
                    attributes = {
                        spacing = "10",
                        padding = "10 10 10 10"
                    },
                    children = {
                        {
                            tag = "Text",
                            attributes = {
                                class = "title",
                                preferredHeight = "80",
                                text = "Test Progress"
                            }
                        },
                        {
                            tag = "Panel",
                            attributes = {
                                preferredWidth = "580",
                                flexibleHeight = "1",
                                color = "#333333",
                                padding = "10 10 0 10",
                                alignment = "MiddleCenter"
                            },
                            children = {
                                {
                                    tag = "VerticalScrollView",
                                    attributes = {
                                        id = "TestScroll",
                                        preferredHeight = "580",
                                        contentSizeFitter = "vertical",
                                        color = "#222222"
                                    },
                                    children = {
                                        {
                                            tag = "VerticalLayout",
                                            attributes = {
                                                preferredHeight = "580",
                                                contentSizeFitter = "vertical"
                                            },
                                            children = {
                                                testGrid,
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    
    return ui, testGrid
end

function onCloseButtonClick()
    local gridOwner = TTSOutput.gridOwner
    local ui = gridOwner and gridOwner.UI or Global.UI
    ui.setAttribute("TestStatus", "active", "false")
end

--- @class GridOutput: genericOutput
GridOutput = { __class__ = "GridOutput" }
setmetatable(GridOutput, { __index = M.genericOutput })

function onTestSquareClick(_, _, id)
    local runner = TTSOutput.currentRunner
    
    local node = runner.result.allTests[tonumber(id)]
    if not node then
        printToAll("No data for test #" .. id, { 1, 0, 0 })
        return
    end
    
    printToAll(M.prettystr(node), Color.fromHex(TTSOutput.colors[node.status] or TTSOutput.colors.UNKNOWN))
end

function GridOutput.new(runner, config)
    local t = M.genericOutput.new(runner)
    runner.gridOwner = config.gridOwner
    t.gridOwner = config.gridOwner
    t.colors = config.colors or TTSOutput.colors
    return setmetatable(t, { __index = GridOutput })
end

function GridOutput:startSuite()
    local clickFunc = resolveClickFunc("onTestSquareClick")
    
    local isGlobal = (self.gridOwner.guid == "-1")
    local origin = isGlobal and "0 0 0" or nil
    local uiTable, testGrid = buildGridUI(origin)
    
    local totalTests = self:totalTests()
    for i = 1, totalTests do
        local id = tostring(i)
        table.insert(testGrid.children, {
            tag = "Button",
            attributes = {
                id = id,
                onClick = clickFunc,
                width = "50",
                height = "50",
                color = self.colors.INFO,
            }
        })
    end
    
    self.gridOwner.UI.setXmlTable(uiTable)
end

function GridOutput:endTest(node)
    local id = tostring(node.number)
    local hex = statusColor(self.colors, node.status)
    self.gridOwner.UI.setAttribute(id, "color", hex)
    if self:totalTests() > 100 then
        local completedTests = node.number
        local percent = 1 - (completedTests / self:totalTests())
        self.gridOwner.UI.setAttribute("TestScroll", "verticalNormalizedPosition", tostring(percent))
    end
end

function GridOutput:totalTests()
    return self.runner.result.selectedCount
end

--[[────────────────────────────────────────────────────────────────────────────
    YieldOutput: Isn't really an Output. It's a counter to yield control
    from LuaUnit code to TTS to allow the various outputs to show up.
    It's configurable, as the yield actually introduces a significant performance
    hit when used with the GridOutput. So, if you don't need it, set it to 0.
────────────────────────────────────────────────────────────────────────────]] --
--- @class YieldOutput: genericOutput
local YieldOutput = { __class__ = "YieldOutput" }
YieldOutput.__index = YieldOutput

--- @param freq   number of tests between each coroutine.yield
function YieldOutput.new(freq)
    return setmetatable({ freq = freq, n = 0 }, YieldOutput)
end

function YieldOutput:startSuite(_)
    coroutine.yield(0)
end

function YieldOutput:endSuite(_)
    coroutine.yield(0)
end

function YieldOutput:endTest(_)
    self.n = self.n + 1
    if self.n % self.freq == 0 then
        coroutine.yield(0)
    end
end

---------------------------------------------------------------
-- Factory method to build the complete output graph
---------------------------------------------------------------
function buildTTSOutput(runner, config)
    local root = TTSMultiOutput.new(runner)
    
    -- ChatOutput (enabled unless explicitly disabled)
    if config.chat ~= false then
        root:add(ChatOutput.new(runner, config.colors, config.chat))
    end
    
    -- LogOutput (enabled unless explicitly disabled)
    if config.log ~= false then
        root:add(LogOutput.new(runner, config.colors, config.log))
    end
    
    -- GridOutput (enabled by default if gridOwner exists)
    if config.grid ~= false and config.gridOwner then
        root:add(GridOutput.new(runner, config))
    end
    
    if config.yieldFrequency then
        root:add(YieldOutput.new(config.yieldFrequency))
    end
    
    return root
end

return TTSOutput

end)
__bundle_register("Test.luaunit", function(require, _LOADED, __bundle_register, __bundle_modules)
--[[
        luaunit.lua

Description: A unit testing framework
Homepage: https://github.com/bluebird75/luaunit
Development by Philippe Fremy <phil@freehackers.org>
Based on initial work of Ryu, Gwang (http://www.gpgstudy.com/gpgiki/LuaUnit)
License: BSD License, see LICENSE.txt
]] --

pcall(require, "math")
local M = {}

-- private exported functions (for testing)
M.private = {}

M.VERSION = '3.4'
M._VERSION = M.VERSION -- For LuaUnit v2 compatibility

-- a version which distinguish between regular Lua and LuaJit
M._LUAVERSION = (jit and jit.version) or _VERSION

--[[ Some people like assertEquals( actual, expected ) and some people prefer
assertEquals( expected, actual ).
]] --
M.ORDER_ACTUAL_EXPECTED              = false
M.PRINT_TABLE_REF_IN_ERROR_MSG       = false
M.LINE_LENGTH                        = 80
M.TABLE_DIFF_ANALYSIS_THRESHOLD      = 10 -- display deep analysis for more than 10 items
M.LIST_DIFF_ANALYSIS_THRESHOLD       = 10 -- display deep analysis for more than 10 items

-- this setting allow to remove entries from the stack-trace, for
-- example to hide a call to a framework which would be calling luaunit
M.STRIP_EXTRA_ENTRIES_IN_STACK_TRACE = 0

--[[ EPS is meant to help with Lua's floating point math in simple corner
cases like almostEquals(1.1-0.1, 1), which may not work as-is (e.g. on numbers
with rational binary representation) if the user doesn't provide some explicit
error margin.

The default margin used by almostEquals() in such cases is EPS; and since
Lua may be compiled with different numeric precisions (single vs. double), we
try to select a useful default for it dynamically. Note: If the initial value
is not acceptable, it can be changed by the user to better suit specific needs.

See also: https://en.wikipedia.org/wiki/Machine_epsilon
]]
M.EPS = 2 ^ -52 -- = machine epsilon for "double", ~2.22E-16
if math.abs(1.1 - 1 - 0.1) > M.EPS then
    -- rounding error is above EPS, assume single precision
    M.EPS = 2 ^ -23 -- = machine epsilon for "float", ~1.19E-07
end

-- set this to false to debug luaunit
local STRIP_LUAUNIT_FROM_STACKTRACE = true

M.VERBOSITY_DEFAULT                 = 10
M.VERBOSITY_LOW                     = 1
M.VERBOSITY_QUIET                   = 0
M.VERBOSITY_VERBOSE                 = 20
M.DEFAULT_DEEP_ANALYSIS             = nil
M.FORCE_DEEP_ANALYSIS               = true
M.DISABLE_DEEP_ANALYSIS             = false

-- set EXPORT_ASSERT_TO_GLOBALS to have all asserts visible as global values
-- EXPORT_ASSERT_TO_GLOBALS = true

-- we need to keep a copy of the script args before it is overriden
local cmdline_argv                  = rawget(_G, "arg")

M.FAILURE_PREFIX                    = 'LuaUnit test FAILURE: ' -- prefix string for failed tests
M.SUCCESS_PREFIX                    = 'LuaUnit test SUCCESS: ' -- prefix string for successful tests finished early
M.SKIP_PREFIX                       = 'LuaUnit test SKIP:    ' -- prefix string for skipped tests



M.USAGE = [[Usage: lua <your_test_suite.lua> [options] [testname1 [testname2] ... ]
Options:
  -h, --help:             Print this help
  --version:              Print version information
  -v, --verbose:          Increase verbosity
  -q, --quiet:            Set verbosity to minimum
  -e, --error:            Stop on first error
  -f, --failure:          Stop on first failure or error
  -s, --shuffle:          Shuffle tests before running them
  -o, --output OUTPUT:    Set output type to OUTPUT
                          Possible values: text, tap, junit, nil
  -n, --name NAME:        For junit only, mandatory name of xml file
  -r, --repeat NUM:       Execute all tests NUM times, e.g. to trig the JIT
  -p, --pattern PATTERN:  Execute all test names matching the Lua PATTERN
                          May be repeated to include several patterns
                          Make sure you escape magic chars like +? with %
  -x, --exclude PATTERN:  Exclude all test names matching the Lua PATTERN
                          May be repeated to exclude several patterns
                          Make sure you escape magic chars like +? with %
  testname1, testname2, ... : tests to run in the form of testFunction,
                              TestClass or TestClass.testMethod

You may also control LuaUnit options with the following environment variables:
* LUAUNIT_OUTPUT: same as --output
* LUAUNIT_JUNIT_FNAME: same as --name ]]

----------------------------------------------------------------
--
--                 general utility functions
--
----------------------------------------------------------------

--[[ Note on catching exit

I have seen the case where running a big suite of test cases and one of them would
perform a os.exit(0), making the outside world think that the full test suite was executed
successfully.

This is an attempt to mitigate this problem: we override os.exit() to now let a test
exit the framework while we are running. When we are not running, it behaves normally.
]]

M.oldOsExit = os.exit
os.exit = function(...)
    if M.LuaUnit and #M.LuaUnit.instances ~= 0 then
        local msg = [[You are trying to exit but there is still a running instance of LuaUnit.
LuaUnit expects to run until the end before exiting with a complete status of successful/failed tests.

To force exit LuaUnit while running, please call before os.exit (assuming lu is the luaunit module loaded):

    lu.unregisterCurrentSuite()

]]
        M.private.error_fmt(2, msg)
    end
    M.oldOsExit(...)
end

local function pcall_or_abort(func, ...)
    -- unpack is a global function for Lua 5.1, otherwise use table.unpack
    local unpack = rawget(_G, "unpack") or table.unpack
    local result = { pcall(func, ...) }
    if not result[1] then
        -- an error occurred
        print(result[2]) -- error message
        print()
        print(M.USAGE)
        os.exit(-1)
    end
    return unpack(result, 2)
end

local crossTypeOrdering = {
    number = 1, boolean = 2, string = 3, table = 4, other = 5
}
local crossTypeComparison = {
    number = function(a, b) return a < b end,
    string = function(a, b) return a < b end,
    other = function(a, b) return tostring(a) < tostring(b) end,
}

local function crossTypeSort(a, b)
    local type_a, type_b = type(a), type(b)
    if type_a == type_b then
        local func = crossTypeComparison[type_a] or crossTypeComparison.other
        return func(a, b)
    end
    type_a = crossTypeOrdering[type_a] or crossTypeOrdering.other
    type_b = crossTypeOrdering[type_b] or crossTypeOrdering.other
    return type_a < type_b
end

local function __genSortedIndex(t)
    -- Returns a sequence consisting of t's keys, sorted.
    local sortedIndex = {}

    for key, _ in pairs(t) do
        table.insert(sortedIndex, key)
    end

    table.sort(sortedIndex, crossTypeSort)
    return sortedIndex
end
M.private.__genSortedIndex = __genSortedIndex

local function sortedNext(state, control)
    -- Equivalent of the next() function of table iteration, but returns the
    -- keys in sorted order (see __genSortedIndex and crossTypeSort).
    -- The state is a temporary variable during iteration and contains the
    -- sorted key table (state.sortedIdx). It also stores the last index (into
    -- the keys) used by the iteration, to find the next one quickly.
    local key

    --print("sortedNext: control = "..tostring(control) )
    if control == nil then
        -- start of iteration
        state.count = #state.sortedIdx
        state.lastIdx = 1
        key = state.sortedIdx[1]
        return key, state.t[key]
    end

    -- normally, we expect the control variable to match the last key used
    if control ~= state.sortedIdx[state.lastIdx] then
        -- strange, we have to find the next value by ourselves
        -- the key table is sorted in crossTypeSort() order! -> use bisection
        local lower, upper = 1, state.count
        repeat
            state.lastIdx = math.modf((lower + upper) / 2)
            key = state.sortedIdx[state.lastIdx]
            if key == control then
                break -- key found (and thus prev index)
            end
            if crossTypeSort(key, control) then
                -- key < control, continue search "right" (towards upper bound)
                lower = state.lastIdx + 1
            else
                -- key > control, continue search "left" (towards lower bound)
                upper = state.lastIdx - 1
            end
        until lower > upper
        if lower > upper then           -- only true if the key wasn't found, ...
            state.lastIdx = state.count -- ... so ensure no match in code below
        end
    end

    -- proceed by retrieving the next value (or nil) from the sorted keys
    state.lastIdx = state.lastIdx + 1
    key = state.sortedIdx[state.lastIdx]
    if key then
        return key, state.t[key]
    end

    -- getting here means returning `nil`, which will end the iteration
end

local function sortedPairs(tbl)
    -- Equivalent of the pairs() function on tables. Allows to iterate in
    -- sorted order. As required by "generic for" loops, this will return the
    -- iterator (function), an "invariant state", and the initial control value.
    -- (see http://www.lua.org/pil/7.2.html)
    return sortedNext, { t = tbl, sortedIdx = __genSortedIndex(tbl) }, nil
end
M.private.sortedPairs = sortedPairs

-- seed the random with a strongly varying seed
math.randomseed(math.floor(os.clock() * 1E11))

local function randomizeTable(t)
    -- randomize the item orders of the table t
    for i = #t, 2, -1 do
        local j = math.random(i)
        if i ~= j then
            t[i], t[j] = t[j], t[i]
        end
    end
end
M.private.randomizeTable = randomizeTable

local function strsplit(delimiter, text)
    -- Split text into a list consisting of the strings in text, separated
    -- by strings matching delimiter (which may _NOT_ be a pattern).
    -- Example: strsplit(", ", "Anna, Bob, Charlie, Dolores")
    if delimiter == "" or delimiter == nil then -- this would result in endless loops
        error("delimiter is nil or empty string!")
    end
    if text == nil then
        return nil
    end

    local list, pos, first, last = {}, 1
    while true do
        first, last = text:find(delimiter, pos, true)
        if first then -- found?
            table.insert(list, text:sub(pos, first - 1))
            pos = last + 1
        else
            table.insert(list, text:sub(pos))
            break
        end
    end
    return list
end
M.private.strsplit = strsplit

local function hasNewLine(s)
    -- return true if s has a newline
    return (string.find(s, '\n', 1, true) ~= nil)
end
M.private.hasNewLine = hasNewLine

local function prefixString(prefix, s)
    -- Prefix all the lines of s with prefix
    return prefix .. string.gsub(s, '\n', '\n' .. prefix)
end
M.private.prefixString = prefixString

local function strMatch(s, pattern, start, final)
    -- return true if s matches completely the pattern from index start to index end
    -- return false in every other cases
    -- if start is nil, matches from the beginning of the string
    -- if final is nil, matches to the end of the string
    start = start or 1
    final = final or string.len(s)

    local foundStart, foundEnd = string.find(s, pattern, start, false)
    return foundStart == start and foundEnd == final
end
M.private.strMatch = strMatch

local function patternFilter(patterns, expr)
    -- Run `expr` through the inclusion and exclusion rules defined in patterns
    -- and return true if expr shall be included, false for excluded.
    -- Inclusion pattern are defined as normal patterns, exclusions
    -- patterns start with `!` and are followed by a normal pattern

    -- result: nil = UNKNOWN (not matched yet), true = ACCEPT, false = REJECT
    -- default: true if no explicit "include" is found, set to false otherwise
    local default, result = true, nil

    if patterns ~= nil then
        for _, pattern in ipairs(patterns) do
            local exclude = pattern:sub(1, 1) == '!'
            if exclude then
                pattern = pattern:sub(2)
            else
                -- at least one include pattern specified, a match is required
                default = false
            end
            -- print('pattern: ',pattern)
            -- print('exclude: ',exclude)
            -- print('default: ',default)

            if string.find(expr, pattern) then
                -- set result to false when excluding, true otherwise
                result = not exclude
            end
        end
    end

    if result ~= nil then
        return result
    end
    return default
end
M.private.patternFilter = patternFilter

local function xmlEscape(s)
    -- Return s escaped for XML attributes
    -- escapes table:
    -- "   &quot;
    -- '   &apos;
    -- <   &lt;
    -- >   &gt;
    -- &   &amp;

    return string.gsub(s, '.', {
        ['&'] = "&amp;",
        ['"'] = "&quot;",
        ["'"] = "&apos;",
        ['<'] = "&lt;",
        ['>'] = "&gt;",
    })
end
M.private.xmlEscape = xmlEscape

local function xmlCDataEscape(s)
    -- Return s escaped for CData section, escapes: "]]>"
    return string.gsub(s, ']]>', ']]&gt;')
end
